WITH total AS (
    SELECT COUNT(id) AS total_cards FROM cards
),
borderless AS (
    SELECT COUNT(id) AS borderless_cards FROM cards WHERE borderColor = 'borderless'
)
SELECT (borderless_cards * 100.0 / total_cards) AS percentage_borderless
FROM total, borderless;

